values ('P0-T1-01', 'P0', 1, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Koperasi sekolah memberi bunga 5% per tahun. Berapa bunga selama 1 tahun untuk tabungan Rp400.000?', '["Rp400.000","5% per tahun","1 tahun"]'::jsonb, '{"modal":400000,"suku_bunga":5,"lama":1,"satuan_lama":"tahun"}'::jsonb, 'bunga', 'rupiah', 20000, 1, '["Diketahui: modal awal M = Rp400.000, suku bunga p = 5 (5% per tahun), lama menabung 1 tahun. Yang ditanya: besar bunga (B).","Gunakan rumus B = M × (p/100) × t.","Lalu masukkan M = 400.000 dan p = 5 ke rumus B = M × (p/100) × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp400.000, suku bunga p = 5 (5% per tahun), lama menabung 1 tahun. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"t = 1 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 400.000 × (5/100) × 1 = 20.000. Jadi besar bunga Rp20.000."},{"langkah":"Periksa","isi":"Bunga 1 tahun adalah 5% dari modal awal, yaitu Rp20.000. Cocok."}]'::jsonb, '[{"jenis":"PERSEN","nilai":2000000,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":420000,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
