values ('M2-T2-02', 'M2', 2, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Hadi menabung Rp3.200.000 di koperasi sekolah dengan suku bunga 5% per tahun. Berapa besar bunga yang Hadi peroleh setelah 4 tahun?', '["Rp3.200.000","5% per tahun","4 tahun"]'::jsonb, '{"modal":3200000,"suku_bunga":5,"lama":4,"satuan_lama":"tahun"}'::jsonb, 'bunga', 'rupiah', 640000, 1, '["Diketahui: modal awal M = Rp3.200.000, suku bunga p = 5 (5% per tahun), lama menabung 4 tahun. Yang ditanya: besar bunga (B).","Gunakan rumus B = M × (p/100) × t.","Lalu masukkan M = 3.200.000 dan p = 5 ke rumus B = M × (p/100) × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp3.200.000, suku bunga p = 5 (5% per tahun), lama menabung 4 tahun. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"t = 4 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 3.200.000 × (5/100) × 4 = 640.000. Jadi besar bunga Rp640.000."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp160.000. Untuk 4 tahun, bunganya 4 × Rp160.000 = Rp640.000. Cocok."}]'::jsonb, '[{"jenis":"PERSEN","nilai":64000000,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":3840000,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
on conflict (kode) do nothing;

