values ('M3-T2-02', 'M3', 2, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Salsa menabung Rp3.600.000 di koperasi sekolah dengan suku bunga 5% per tahun. Berapa besar bunga yang Salsa peroleh setelah 8 bulan?', '["Rp3.600.000","5% per tahun","8 bulan"]'::jsonb, '{"modal":3600000,"suku_bunga":5,"lama":8,"satuan_lama":"bulan"}'::jsonb, 'bunga', 'rupiah', 120000, 1, '["Diketahui: modal awal M = Rp3.600.000, suku bunga p = 5 (5% per tahun), lama menabung 8 bulan. Yang ditanya: besar bunga (B).","Gunakan rumus B = M × (p/100) × t. Ingat, t harus dalam tahun.","Ubah dulu 8 bulan menjadi tahun: t = 8/12. Lalu masukkan M = 3.600.000 dan p = 5 ke rumus B = M × (p/100) × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp3.600.000, suku bunga p = 5 (5% per tahun), lama menabung 8 bulan. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 8/12 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 3.600.000 × (5/100) × (8/12) = 120.000. Jadi besar bunga Rp120.000."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp180.000. Lama menabung kurang dari 1 tahun, jadi bunganya lebih kecil. Rp120.000 masuk akal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":1440000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 8 bulan = 8/12 tahun."},{"jenis":"PERSEN","nilai":12000000,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":3720000,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
on conflict (kode) do nothing;

