values ('M3-T2-03', 'M3', 2, 'latihan', 'isian', null, null, 'koperasi', 'Tono menabung Rp4.200.000 di koperasi dengan suku bunga 6% per tahun. Berapa besar bunga yang Tono peroleh setelah 10 bulan?', '["Rp4.200.000","6% per tahun","10 bulan"]'::jsonb, '{"modal":4200000,"suku_bunga":6,"lama":10,"satuan_lama":"bulan"}'::jsonb, 'bunga', 'rupiah', 210000, 1, '["Diketahui: modal awal M = Rp4.200.000, suku bunga p = 6 (6% per tahun), lama menabung 10 bulan. Yang ditanya: besar bunga (B).","Gunakan rumus B = M × (p/100) × t. Ingat, t harus dalam tahun.","Ubah dulu 10 bulan menjadi tahun: t = 10/12. Lalu masukkan M = 4.200.000 dan p = 6 ke rumus B = M × (p/100) × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp4.200.000, suku bunga p = 6 (6% per tahun), lama menabung 10 bulan. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 10/12 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 4.200.000 × (6/100) × (10/12) = 210.000. Jadi besar bunga Rp210.000."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp252.000. Lama menabung kurang dari 1 tahun, jadi bunganya lebih kecil. Rp210.000 masuk akal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":2520000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 10 bulan = 10/12 tahun."},{"jenis":"PERSEN","nilai":21000000,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":4410000,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
