values ('M3-T3-04', 'M3', 3, 'latihan', 'isian', null, null, 'bank', 'Zahra menabung Rp5.475.000 di bank dengan suku bunga 4% per tahun. Berapa besar bunga yang Zahra peroleh setelah 292 hari?', '["Rp5.475.000","4% per tahun","292 hari"]'::jsonb, '{"modal":5475000,"suku_bunga":4,"lama":292,"satuan_lama":"hari"}'::jsonb, 'bunga', 'rupiah', 175200, 1, '["Diketahui: modal awal M = Rp5.475.000, suku bunga p = 4 (4% per tahun), lama menabung 292 hari. Yang ditanya: besar bunga (B).","Gunakan rumus B = M × (p/100) × t. Ingat, t harus dalam tahun.","Ubah dulu 292 hari menjadi tahun: t = 292/365. Lalu masukkan M = 5.475.000 dan p = 4 ke rumus B = M × (p/100) × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp5.475.000, suku bunga p = 4 (4% per tahun), lama menabung 292 hari. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam hari, jadi t = 292/365 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 5.475.000 × (4/100) × (292/365) = 175.200. Jadi besar bunga Rp175.200."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp219.000. Lama menabung kurang dari 1 tahun, jadi bunganya lebih kecil. Rp175.200 masuk akal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":63948000,"pesan":"Lama menabung dalam hari. Ubah dulu ke tahun: 292 hari = 292/365 tahun."},{"jenis":"PERSEN","nilai":17520000,"pesan":"Ingat, suku bunga 4% ditulis p/100 = 4/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":5650200,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
