values ('M4-T1-01', 'M4', 1, 'latihan', 'isian', null, null, 'bank', 'Rani menabung Rp1.000.000 di bank dengan suku bunga 6% per tahun. Berapa jumlah tabungan Rani setelah 2 tahun?', '["Rp1.000.000","6% per tahun","2 tahun"]'::jsonb, '{"modal":1000000,"suku_bunga":6,"lama":2,"satuan_lama":"tahun"}'::jsonb, 'tabungan_akhir', 'rupiah', 1120000, 1, '["Diketahui: modal awal M = Rp1.000.000, suku bunga p = 6 (6% per tahun), lama menabung 2 tahun. Yang ditanya: jumlah tabungan akhir (A).","Gunakan rumus B = M × (p/100) × t, lalu A = M + B.","Lalu masukkan M = 1.000.000 dan p = 6 ke rumus B = M × (p/100) × t. Setelah B didapat, tambahkan ke modal awal."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.000.000, suku bunga p = 6 (6% per tahun), lama menabung 2 tahun. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"t = 2 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 1.000.000 × (6/100) × 2 = 120.000. A = 1.000.000 + 120.000 = 1.120.000. Jadi jumlah tabungan akhir Rp1.120.000."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp120.000 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"PERSEN","nilai":13000000,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":120000,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
on conflict (kode) do nothing;

