values ('M4-T1-02', 'M4', 1, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Budi menabung Rp2.000.000 di koperasi sekolah dengan suku bunga 5% per tahun. Berapa jumlah tabungan Budi setelah 1 tahun?', '["Rp2.000.000","5% per tahun","1 tahun"]'::jsonb, '{"modal":2000000,"suku_bunga":5,"lama":1,"satuan_lama":"tahun"}'::jsonb, 'tabungan_akhir', 'rupiah', 2100000, 1, '["Diketahui: modal awal M = Rp2.000.000, suku bunga p = 5 (5% per tahun), lama menabung 1 tahun. Yang ditanya: jumlah tabungan akhir (A).","Gunakan rumus B = M × (p/100) × t, lalu A = M + B.","Lalu masukkan M = 2.000.000 dan p = 5 ke rumus B = M × (p/100) × t. Setelah B didapat, tambahkan ke modal awal."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.000.000, suku bunga p = 5 (5% per tahun), lama menabung 1 tahun. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"t = 1 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 2.000.000 × (5/100) × 1 = 100.000. A = 2.000.000 + 100.000 = 2.100.000. Jadi jumlah tabungan akhir Rp2.100.000."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp100.000 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"PERSEN","nilai":12000000,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":100000,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
