values ('M4-T2-01', 'M4', 2, 'latihan', 'isian', null, null, 'koperasi', 'Dimas menabung Rp1.200.000 di koperasi dengan suku bunga 10% per tahun. Berapa jumlah tabungan Dimas setelah 6 bulan?', '["Rp1.200.000","10% per tahun","6 bulan"]'::jsonb, '{"modal":1200000,"suku_bunga":10,"lama":6,"satuan_lama":"bulan"}'::jsonb, 'tabungan_akhir', 'rupiah', 1260000, 1, '["Diketahui: modal awal M = Rp1.200.000, suku bunga p = 10 (10% per tahun), lama menabung 6 bulan. Yang ditanya: jumlah tabungan akhir (A).","Gunakan rumus B = M × (p/100) × t, lalu A = M + B. Ingat, t harus dalam tahun.","Ubah dulu 6 bulan menjadi tahun: t = 6/12. Lalu masukkan M = 1.200.000 dan p = 10 ke rumus B = M × (p/100) × t. Setelah B didapat, tambahkan ke modal awal."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.200.000, suku bunga p = 10 (10% per tahun), lama menabung 6 bulan. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 6/12 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 1.200.000 × (10/100) × (6/12) = 60.000. A = 1.200.000 + 60.000 = 1.260.000. Jadi jumlah tabungan akhir Rp1.260.000."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp60.000 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":1920000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 6 bulan = 6/12 tahun."},{"jenis":"PERSEN","nilai":7200000,"pesan":"Ingat, suku bunga 10% ditulis p/100 = 10/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":60000,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
on conflict (kode) do nothing;

