values ('M4-T3-01', 'M4', 3, 'latihan', 'isian', null, null, 'bank', 'Tia menabung Rp3.650.000 di bank dengan suku bunga 8% per tahun. Berapa jumlah tabungan Tia setelah 146 hari?', '["Rp3.650.000","8% per tahun","146 hari"]'::jsonb, '{"modal":3650000,"suku_bunga":8,"lama":146,"satuan_lama":"hari"}'::jsonb, 'tabungan_akhir', 'rupiah', 3766800, 1, '["Diketahui: modal awal M = Rp3.650.000, suku bunga p = 8 (8% per tahun), lama menabung 146 hari. Yang ditanya: jumlah tabungan akhir (A).","Gunakan rumus B = M × (p/100) × t, lalu A = M + B. Ingat, t harus dalam tahun.","Ubah dulu 146 hari menjadi tahun: t = 146/365. Lalu masukkan M = 3.650.000 dan p = 8 ke rumus B = M × (p/100) × t. Setelah B didapat, tambahkan ke modal awal."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp3.650.000, suku bunga p = 8 (8% per tahun), lama menabung 146 hari. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam hari, jadi t = 146/365 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 3.650.000 × (8/100) × (146/365) = 116.800. A = 3.650.000 + 116.800 = 3.766.800. Jadi jumlah tabungan akhir Rp3.766.800."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp116.800 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":46282000,"pesan":"Lama menabung dalam hari. Ubah dulu ke tahun: 146 hari = 146/365 tahun."},{"jenis":"PERSEN","nilai":15330000,"pesan":"Ingat, suku bunga 8% ditulis p/100 = 8/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":116800,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
