values ('M4-T3-02', 'M4', 3, 'latihan', 'isian', null, null, 'koperasi', 'Nina menabung Rp4.500.000 di koperasi dengan suku bunga 6% per tahun. Berapa jumlah tabungan Nina setelah 15 bulan?', '["Rp4.500.000","6% per tahun","15 bulan"]'::jsonb, '{"modal":4500000,"suku_bunga":6,"lama":15,"satuan_lama":"bulan"}'::jsonb, 'tabungan_akhir', 'rupiah', 4837500, 1, '["Diketahui: modal awal M = Rp4.500.000, suku bunga p = 6 (6% per tahun), lama menabung 15 bulan. Yang ditanya: jumlah tabungan akhir (A).","Gunakan rumus B = M × (p/100) × t, lalu A = M + B. Ingat, t harus dalam tahun.","Ubah dulu 15 bulan menjadi tahun: t = 15/12. Lalu masukkan M = 4.500.000 dan p = 6 ke rumus B = M × (p/100) × t. Setelah B didapat, tambahkan ke modal awal."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp4.500.000, suku bunga p = 6 (6% per tahun), lama menabung 15 bulan. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 15/12 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 4.500.000 × (6/100) × (15/12) = 337.500. A = 4.500.000 + 337.500 = 4.837.500. Jadi jumlah tabungan akhir Rp4.837.500."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp337.500 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":8550000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 15 bulan = 15/12 tahun."},{"jenis":"PERSEN","nilai":38250000,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":337500,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
