values ('M4-T3-03', 'M4', 3, 'latihan', 'isian', null, null, 'bank', 'Fajar menabung Rp2.920.000 di bank untuk membeli laptop. Suku bunganya 5% per tahun. Berapa jumlah tabungan akhir Fajar setelah 73 hari?', '["Rp2.920.000","5% per tahun","73 hari"]'::jsonb, '{"modal":2920000,"suku_bunga":5,"lama":73,"satuan_lama":"hari"}'::jsonb, 'tabungan_akhir', 'rupiah', 2949200, 1, '["Diketahui: modal awal M = Rp2.920.000, suku bunga p = 5 (5% per tahun), lama menabung 73 hari. Yang ditanya: jumlah tabungan akhir (A).","Gunakan rumus B = M × (p/100) × t, lalu A = M + B. Ingat, t harus dalam tahun.","Ubah dulu 73 hari menjadi tahun: t = 73/365. Lalu masukkan M = 2.920.000 dan p = 5 ke rumus B = M × (p/100) × t. Setelah B didapat, tambahkan ke modal awal."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.920.000, suku bunga p = 5 (5% per tahun), lama menabung 73 hari. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam hari, jadi t = 73/365 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 2.920.000 × (5/100) × (73/365) = 29.200. A = 2.920.000 + 29.200 = 2.949.200. Jadi jumlah tabungan akhir Rp2.949.200."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp29.200 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":13578000,"pesan":"Lama menabung dalam hari. Ubah dulu ke tahun: 73 hari = 73/365 tahun."},{"jenis":"PERSEN","nilai":5840000,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":29200,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T1-01', 'M5', 1, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Gita menabung di koperasi sekolah dengan suku bunga 5% per tahun. Setelah 2 tahun, ia mendapat bunga Rp100.000. Berapa modal awal Gita?', '["5% per tahun","2 tahun","Rp100.000"]'::jsonb, '{"bunga":100000,"suku_bunga":5,"lama":2,"satuan_lama":"tahun"}'::jsonb, 'modal', 'rupiah', 1000000, 1, '["Diketahui: suku bunga p = 5 (5% per tahun), lama menabung 2 tahun, besar bunga B = Rp100.000. Yang ditanya: modal awal (M).","Gunakan rumus M = B ÷ ((p/100) × t).","Hitung dulu (p/100) × t = (5/100) × 2. Lalu bagi besar bunga dengan hasil itu."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui suku bunga p = 5 (5% per tahun), lama menabung 2 tahun, besar bunga B = Rp100.000. Ditanya: modal awal (M)."},{"langkah":"Rencanakan","isi":"t = 2 tahun. Rumus: M = B ÷ ((p/100) × t)."},{"langkah":"Hitung","isi":"(p/100) × t = (5/100) × 2 = 0,1. M = 100.000 ÷ 0,1 = 1.000.000. Jadi modal awal Rp1.000.000."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 1.000.000 × (5/100) × 2 = Rp100.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"RUMUS_INVERS","nilai":10000,"pesan":"Untuk mencari modal awal, bagi besar bunga dengan ((p/100) × t), jangan dikalikan."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T1-02', 'M5', 1, 'latihan', 'isian', null, null, 'bank', 'Hadi menabung Rp1.500.000 di bank. Setelah 2 tahun, ia mendapat bunga Rp120.000. Berapa suku bunga per tahunnya?', '["Rp1.500.000","2 tahun","Rp120.000"]'::jsonb, '{"modal":1500000,"bunga":120000,"lama":2,"satuan_lama":"tahun"}'::jsonb, 'suku_bunga', 'persen', 4, 0.01, '["Diketahui: modal awal M = Rp1.500.000, lama menabung 2 tahun, besar bunga B = Rp120.000. Yang ditanya: suku bunga per tahun (p).","Gunakan rumus p = (B × 100) ÷ (M × t).","Kalikan besar bunga dengan 100, lalu bagi dengan M × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.500.000, lama menabung 2 tahun, besar bunga B = Rp120.000. Ditanya: suku bunga per tahun (p)."},{"langkah":"Rencanakan","isi":"t = 2 tahun. Rumus: p = (B × 100) ÷ (M × t)."},{"langkah":"Hitung","isi":"p = (120.000 × 100) ÷ (1.500.000 × 2) = 4. Jadi suku bunganya 4% per tahun."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 1.500.000 × (4/100) × 2 = Rp120.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"PERSEN","nilai":0.04,"pesan":"Hasil baginya masih berupa pecahan. Kalikan dengan 100 agar menjadi persen: p = (B × 100) ÷ (M × t)."},{"jenis":"RUMUS_INVERS","nilai":8,"pesan":"Untuk mencari suku bunga, gunakan p = (B × 100) ÷ (M × t). Jangan lupa membagi dengan lama menabung."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T1-03', 'M5', 1, 'latihan', 'isian', null, null, 'koperasi', 'Intan menabung Rp1.000.000 di koperasi dengan suku bunga 10% per tahun. Setelah beberapa waktu, ia mendapat bunga Rp300.000. Berapa tahun Intan menabung?', '["Rp1.000.000","10% per tahun","Rp300.000"]'::jsonb, '{"modal":1000000,"suku_bunga":10,"bunga":300000}'::jsonb, 'lama', 'tahun', 3, 0.01, '["Diketahui: modal awal M = Rp1.000.000, suku bunga p = 10 (10% per tahun), besar bunga B = Rp300.000. Yang ditanya: lama menabung (dalam tahun).","Gunakan rumus t = (B × 100) ÷ (M × p).","Kalikan besar bunga dengan 100, lalu bagi dengan M × p = 1.000.000 × 10."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.000.000, suku bunga p = 10 (10% per tahun), besar bunga B = Rp300.000. Ditanya: lama menabung (dalam tahun)."},{"langkah":"Rencanakan","isi":"Rumus: t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"t = (300.000 × 100) ÷ (1.000.000 × 10) = 3 tahun. Jadi lama menabung 3 tahun."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 1.000.000 × (10/100) × 3 = Rp300.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":36,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam tahun, bukan bulan."},{"jenis":"PERSEN","nilai":0.03,"pesan":"Ingat, suku bunga 10% ditulis p/100 = 10/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":0.3333,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T1-04', 'M5', 1, 'latihan', 'isian', null, null, 'bank desa', 'Joko menabung di bank desa dengan suku bunga 4% per tahun. Setelah 3 tahun, ia mendapat bunga Rp300.000. Berapa modal awal Joko?', '["4% per tahun","3 tahun","Rp300.000"]'::jsonb, '{"bunga":300000,"suku_bunga":4,"lama":3,"satuan_lama":"tahun"}'::jsonb, 'modal', 'rupiah', 2500000, 1, '["Diketahui: suku bunga p = 4 (4% per tahun), lama menabung 3 tahun, besar bunga B = Rp300.000. Yang ditanya: modal awal (M).","Gunakan rumus M = B ÷ ((p/100) × t).","Hitung dulu (p/100) × t = (4/100) × 3. Lalu bagi besar bunga dengan hasil itu."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui suku bunga p = 4 (4% per tahun), lama menabung 3 tahun, besar bunga B = Rp300.000. Ditanya: modal awal (M)."},{"langkah":"Rencanakan","isi":"t = 3 tahun. Rumus: M = B ÷ ((p/100) × t)."},{"langkah":"Hitung","isi":"(p/100) × t = (4/100) × 3 = 0,12. M = 300.000 ÷ 0,12 = 2.500.000. Jadi modal awal Rp2.500.000."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.500.000 × (4/100) × 3 = Rp300.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"RUMUS_INVERS","nilai":36000,"pesan":"Untuk mencari modal awal, bagi besar bunga dengan ((p/100) × t), jangan dikalikan."},{"jenis":"PERSEN","nilai":25000,"pesan":"Ingat, suku bunga 4% ditulis p/100 = 4/100 di dalam rumus."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T1-05', 'M5', 1, 'latihan', 'isian', null, null, 'bank', 'Kiki menabung Rp3.000.000 di bank. Setelah 4 tahun, ia mendapat bunga Rp600.000. Berapa suku bunga per tahunnya?', '["Rp3.000.000","4 tahun","Rp600.000"]'::jsonb, '{"modal":3000000,"bunga":600000,"lama":4,"satuan_lama":"tahun"}'::jsonb, 'suku_bunga', 'persen', 5, 0.01, '["Diketahui: modal awal M = Rp3.000.000, lama menabung 4 tahun, besar bunga B = Rp600.000. Yang ditanya: suku bunga per tahun (p).","Gunakan rumus p = (B × 100) ÷ (M × t).","Kalikan besar bunga dengan 100, lalu bagi dengan M × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp3.000.000, lama menabung 4 tahun, besar bunga B = Rp600.000. Ditanya: suku bunga per tahun (p)."},{"langkah":"Rencanakan","isi":"t = 4 tahun. Rumus: p = (B × 100) ÷ (M × t)."},{"langkah":"Hitung","isi":"p = (600.000 × 100) ÷ (3.000.000 × 4) = 5. Jadi suku bunganya 5% per tahun."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 3.000.000 × (5/100) × 4 = Rp600.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"PERSEN","nilai":0.05,"pesan":"Hasil baginya masih berupa pecahan. Kalikan dengan 100 agar menjadi persen: p = (B × 100) ÷ (M × t)."},{"jenis":"RUMUS_INVERS","nilai":20,"pesan":"Untuk mencari suku bunga, gunakan p = (B × 100) ÷ (M × t). Jangan lupa membagi dengan lama menabung."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T2-01', 'M5', 2, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Lukman menabung di koperasi sekolah dengan suku bunga 6% per tahun. Setelah 8 bulan, ia mendapat bunga Rp96.000. Berapa modal awal Lukman?', '["6% per tahun","8 bulan","Rp96.000"]'::jsonb, '{"bunga":96000,"suku_bunga":6,"lama":8,"satuan_lama":"bulan"}'::jsonb, 'modal', 'rupiah', 2400000, 1, '["Diketahui: suku bunga p = 6 (6% per tahun), lama menabung 8 bulan, besar bunga B = Rp96.000. Yang ditanya: modal awal (M).","Gunakan rumus M = B ÷ ((p/100) × t). Ingat, t harus dalam tahun.","Ubah dulu 8 bulan menjadi tahun: t = 8/12. Hitung dulu (p/100) × t = (6/100) × (8/12). Lalu bagi besar bunga dengan hasil itu."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui suku bunga p = 6 (6% per tahun), lama menabung 8 bulan, besar bunga B = Rp96.000. Ditanya: modal awal (M)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 8/12 tahun. Rumus: M = B ÷ ((p/100) × t)."},{"langkah":"Hitung","isi":"(p/100) × t = (6/100) × (8/12) = 0,04. M = 96.000 ÷ 0,04 = 2.400.000. Jadi modal awal Rp2.400.000."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.400.000 × (6/100) × (8/12) = Rp96.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"RUMUS_INVERS","nilai":3840,"pesan":"Untuk mencari modal awal, bagi besar bunga dengan ((p/100) × t), jangan dikalikan."},{"jenis":"SATUAN_WAKTU","nilai":200000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 8 bulan = 8/12 tahun."},{"jenis":"PERSEN","nilai":24000,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T2-02', 'M5', 2, 'latihan', 'isian', null, null, 'bank', 'Maya menabung Rp1.200.000 di bank. Setelah 6 bulan, ia mendapat bunga Rp42.000. Berapa suku bunga per tahunnya?', '["Rp1.200.000","6 bulan","Rp42.000"]'::jsonb, '{"modal":1200000,"bunga":42000,"lama":6,"satuan_lama":"bulan"}'::jsonb, 'suku_bunga', 'persen', 7, 0.01, '["Diketahui: modal awal M = Rp1.200.000, lama menabung 6 bulan, besar bunga B = Rp42.000. Yang ditanya: suku bunga per tahun (p).","Gunakan rumus p = (B × 100) ÷ (M × t). Ingat, t harus dalam tahun.","Ubah dulu 6 bulan menjadi tahun: t = 6/12. Kalikan besar bunga dengan 100, lalu bagi dengan M × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.200.000, lama menabung 6 bulan, besar bunga B = Rp42.000. Ditanya: suku bunga per tahun (p)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 6/12 tahun. Rumus: p = (B × 100) ÷ (M × t)."},{"langkah":"Hitung","isi":"p = (42.000 × 100) ÷ (1.200.000 × (6/12)) = 7. Jadi suku bunganya 7% per tahun."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 1.200.000 × (7/100) × (6/12) = Rp42.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"PERSEN","nilai":0.07,"pesan":"Hasil baginya masih berupa pecahan. Kalikan dengan 100 agar menjadi persen: p = (B × 100) ÷ (M × t)."},{"jenis":"SATUAN_WAKTU","nilai":0.5833,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 6 bulan = 6/12 tahun."},{"jenis":"RUMUS_INVERS","nilai":3.5,"pesan":"Untuk mencari suku bunga, gunakan p = (B × 100) ÷ (M × t). Jangan lupa membagi dengan lama menabung."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T2-03', 'M5', 2, 'latihan', 'isian', null, null, 'koperasi', 'Nanda menabung Rp2.000.000 di koperasi dengan suku bunga 6% per tahun. Setelah beberapa waktu, ia mendapat bunga Rp90.000. Berapa bulan Nanda menabung?', '["Rp2.000.000","6% per tahun","Rp90.000"]'::jsonb, '{"modal":2000000,"suku_bunga":6,"bunga":90000}'::jsonb, 'lama', 'bulan', 9, 0.01, '["Diketahui: modal awal M = Rp2.000.000, suku bunga p = 6 (6% per tahun), besar bunga B = Rp90.000. Yang ditanya: lama menabung (dalam bulan).","Gunakan rumus t = (B × 100) ÷ (M × p). Hasil t dalam tahun, lalu ubah ke bulan.","Kalikan besar bunga dengan 100, lalu bagi dengan M × p = 2.000.000 × 6."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.000.000, suku bunga p = 6 (6% per tahun), besar bunga B = Rp90.000. Ditanya: lama menabung (dalam bulan)."},{"langkah":"Rencanakan","isi":"Rumus: t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"t = (90.000 × 100) ÷ (2.000.000 × 6) = 0,75 tahun. Ubah ke bulan: 0,75 × 12 = 9 bulan. Jadi lama menabung 9 bulan."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.000.000 × (6/100) × (9/12) = Rp90.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":0.75,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam bulan. Ubah hasil dalam tahun ke bulan."},{"jenis":"PERSEN","nilai":0.09,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":16,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."}]'::jsonb)
on conflict (kode) do nothing;

