values ('M5-T2-04', 'M5', 2, 'latihan', 'isian', null, null, 'bank desa', 'Oki menabung Rp1.800.000 di bank desa dengan suku bunga 8% per tahun. Setelah beberapa waktu, ia mendapat bunga Rp72.000. Berapa bulan Oki menabung?', '["Rp1.800.000","8% per tahun","Rp72.000"]'::jsonb, '{"modal":1800000,"suku_bunga":8,"bunga":72000}'::jsonb, 'lama', 'bulan', 6, 0.01, '["Diketahui: modal awal M = Rp1.800.000, suku bunga p = 8 (8% per tahun), besar bunga B = Rp72.000. Yang ditanya: lama menabung (dalam bulan).","Gunakan rumus t = (B × 100) ÷ (M × p). Hasil t dalam tahun, lalu ubah ke bulan.","Kalikan besar bunga dengan 100, lalu bagi dengan M × p = 1.800.000 × 8."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.800.000, suku bunga p = 8 (8% per tahun), besar bunga B = Rp72.000. Ditanya: lama menabung (dalam bulan)."},{"langkah":"Rencanakan","isi":"Rumus: t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"t = (72.000 × 100) ÷ (1.800.000 × 8) = 0,5 tahun. Ubah ke bulan: 0,5 × 12 = 6 bulan. Jadi lama menabung 6 bulan."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 1.800.000 × (8/100) × (6/12) = Rp72.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":0.5,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam bulan. Ubah hasil dalam tahun ke bulan."},{"jenis":"PERSEN","nilai":0.06,"pesan":"Ingat, suku bunga 8% ditulis p/100 = 8/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":24,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T2-05', 'M5', 2, 'latihan', 'isian', null, null, 'bank', 'Putri menabung di bank dengan suku bunga 9% per tahun. Setelah 4 bulan, ia mendapat bunga Rp90.000. Berapa modal awal Putri?', '["9% per tahun","4 bulan","Rp90.000"]'::jsonb, '{"bunga":90000,"suku_bunga":9,"lama":4,"satuan_lama":"bulan"}'::jsonb, 'modal', 'rupiah', 3000000, 1, '["Diketahui: suku bunga p = 9 (9% per tahun), lama menabung 4 bulan, besar bunga B = Rp90.000. Yang ditanya: modal awal (M).","Gunakan rumus M = B ÷ ((p/100) × t). Ingat, t harus dalam tahun.","Ubah dulu 4 bulan menjadi tahun: t = 4/12. Hitung dulu (p/100) × t = (9/100) × (4/12). Lalu bagi besar bunga dengan hasil itu."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui suku bunga p = 9 (9% per tahun), lama menabung 4 bulan, besar bunga B = Rp90.000. Ditanya: modal awal (M)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 4/12 tahun. Rumus: M = B ÷ ((p/100) × t)."},{"langkah":"Hitung","isi":"(p/100) × t = (9/100) × (4/12) = 0,03. M = 90.000 ÷ 0,03 = 3.000.000. Jadi modal awal Rp3.000.000."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 3.000.000 × (9/100) × (4/12) = Rp90.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"RUMUS_INVERS","nilai":2700,"pesan":"Untuk mencari modal awal, bagi besar bunga dengan ((p/100) × t), jangan dikalikan."},{"jenis":"SATUAN_WAKTU","nilai":250000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 4 bulan = 4/12 tahun."},{"jenis":"PERSEN","nilai":30000,"pesan":"Ingat, suku bunga 9% ditulis p/100 = 9/100 di dalam rumus."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T3-01', 'M5', 3, 'latihan', 'isian', null, null, 'koperasi', 'Setelah menabung 6 bulan di koperasi dengan suku bunga 6% per tahun, jumlah tabungan Raka menjadi Rp2.060.000. Berapa modal awal Raka?', '["6% per tahun","6 bulan","Rp2.060.000"]'::jsonb, '{"tabungan_akhir":2060000,"suku_bunga":6,"lama":6,"satuan_lama":"bulan"}'::jsonb, 'modal', 'rupiah', 2000000, 1, '["Diketahui: suku bunga p = 6 (6% per tahun), lama menabung 6 bulan, jumlah tabungan akhir (A) = Rp2.060.000. Yang ditanya: modal awal (M).","Gunakan rumus M = A ÷ (1 + (p/100) × t). Ingat, t harus dalam tahun.","Ubah dulu 6 bulan menjadi tahun: t = 6/12. Hitung dulu (p/100) × t = (6/100) × (6/12). Lalu bagi jumlah tabungan akhir dengan (1 + hasil itu)."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui suku bunga p = 6 (6% per tahun), lama menabung 6 bulan, jumlah tabungan akhir (A) = Rp2.060.000. Ditanya: modal awal (M)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 6/12 tahun. Rumus: M = A ÷ (1 + (p/100) × t)."},{"langkah":"Hitung","isi":"(p/100) × t = (6/100) × (6/12) = 0,03. M = 2.060.000 ÷ (1 + 0,03) = 2.000.000. Jadi modal awal Rp2.000.000."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.000.000 × (6/100) × (6/12) = Rp60.000, dan M + B = Rp2.060.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":68666666.6667,"pesan":"Pada soal, Rp2.060.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Karena A = M + B, modal awal M = A ÷ (1 + (p/100) × t)."},{"jenis":"RUMUS_INVERS","nilai":1998200,"pesan":"Bunga dihitung dari modal awal, bukan dari jumlah tabungan akhir. Gunakan M = A ÷ (1 + (p/100) × t)."},{"jenis":"SATUAN_WAKTU","nilai":1514705.8824,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 6 bulan = 6/12 tahun."},{"jenis":"PERSEN","nilai":515000,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T3-02', 'M5', 3, 'latihan', 'isian', null, null, 'bank', 'Salsa menabung Rp2.500.000 di bank. Setelah 9 bulan, jumlah tabungannya menjadi Rp2.650.000. Berapa suku bunga per tahunnya?', '["Rp2.500.000","9 bulan","Rp2.650.000"]'::jsonb, '{"modal":2500000,"tabungan_akhir":2650000,"lama":9,"satuan_lama":"bulan"}'::jsonb, 'suku_bunga', 'persen', 8, 0.01, '["Diketahui: modal awal M = Rp2.500.000, lama menabung 9 bulan, jumlah tabungan akhir (A) = Rp2.650.000. Yang ditanya: suku bunga per tahun (p).","Gunakan rumus B = A − M, lalu p = (B × 100) ÷ (M × t). Ingat, t harus dalam tahun.","Ubah dulu 9 bulan menjadi tahun: t = 9/12. Cari besar bunga dulu: B = 2.650.000 − 2.500.000. Kalikan besar bunga dengan 100, lalu bagi dengan M × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.500.000, lama menabung 9 bulan, jumlah tabungan akhir (A) = Rp2.650.000. Ditanya: suku bunga per tahun (p)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 9/12 tahun. Rumus: B = A − M, lalu p = (B × 100) ÷ (M × t)."},{"langkah":"Hitung","isi":"B = 2.650.000 − 2.500.000 = 150.000. p = (150.000 × 100) ÷ (2.500.000 × (9/12)) = 8. Jadi suku bunganya 8% per tahun."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.500.000 × (8/100) × (9/12) = Rp150.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"PERSEN","nilai":0.08,"pesan":"Hasil baginya masih berupa pecahan. Kalikan dengan 100 agar menjadi persen: p = (B × 100) ÷ (M × t)."},{"jenis":"SATUAN_WAKTU","nilai":0.6667,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 9 bulan = 9/12 tahun."},{"jenis":"RUMUS_INVERS","nilai":6,"pesan":"Untuk mencari suku bunga, gunakan p = (B × 100) ÷ (M × t). Jangan lupa membagi dengan lama menabung."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":141.3333,"pesan":"Pada soal, Rp2.650.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T3-03', 'M5', 3, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Tono menabung Rp2.400.000 di koperasi sekolah dengan suku bunga 5% per tahun. Setelah beberapa waktu, jumlah tabungannya menjadi Rp2.550.000. Berapa bulan Tono menabung?', '["Rp2.400.000","5% per tahun","Rp2.550.000"]'::jsonb, '{"modal":2400000,"suku_bunga":5,"tabungan_akhir":2550000}'::jsonb, 'lama', 'bulan', 15, 0.01, '["Diketahui: modal awal M = Rp2.400.000, suku bunga p = 5 (5% per tahun), jumlah tabungan akhir (A) = Rp2.550.000. Yang ditanya: lama menabung (dalam bulan).","Gunakan rumus B = A − M, lalu t = (B × 100) ÷ (M × p). Hasil t dalam tahun, lalu ubah ke bulan.","Cari besar bunga dulu: B = 2.550.000 − 2.400.000. Kalikan besar bunga dengan 100, lalu bagi dengan M × p = 2.400.000 × 5."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.400.000, suku bunga p = 5 (5% per tahun), jumlah tabungan akhir (A) = Rp2.550.000. Ditanya: lama menabung (dalam bulan)."},{"langkah":"Rencanakan","isi":"Rumus: B = A − M, lalu t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"B = 2.550.000 − 2.400.000 = 150.000. t = (150.000 × 100) ÷ (2.400.000 × 5) = 1,25 tahun. Ubah ke bulan: 1,25 × 12 = 15 bulan. Jadi lama menabung 15 bulan."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.400.000 × (5/100) × (15/12) = Rp150.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":1.25,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam bulan. Ubah hasil dalam tahun ke bulan."},{"jenis":"PERSEN","nilai":0.15,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":9.6,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":255,"pesan":"Pada soal, Rp2.550.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M5-T3-04', 'M5', 3, 'latihan', 'isian', null, null, 'bank desa', 'Umi menabung Rp3.650.000 di bank desa dengan suku bunga 10% per tahun. Setelah beberapa waktu, jumlah tabungannya menjadi Rp3.723.000. Berapa hari Umi menabung?', '["Rp3.650.000","10% per tahun","Rp3.723.000"]'::jsonb, '{"modal":3650000,"suku_bunga":10,"tabungan_akhir":3723000}'::jsonb, 'lama', 'hari', 73, 0.01, '["Diketahui: modal awal M = Rp3.650.000, suku bunga p = 10 (10% per tahun), jumlah tabungan akhir (A) = Rp3.723.000. Yang ditanya: lama menabung (dalam hari).","Gunakan rumus B = A − M, lalu t = (B × 100) ÷ (M × p). Hasil t dalam tahun, lalu ubah ke hari.","Cari besar bunga dulu: B = 3.723.000 − 3.650.000. Kalikan besar bunga dengan 100, lalu bagi dengan M × p = 3.650.000 × 10."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp3.650.000, suku bunga p = 10 (10% per tahun), jumlah tabungan akhir (A) = Rp3.723.000. Ditanya: lama menabung (dalam hari)."},{"langkah":"Rencanakan","isi":"Rumus: B = A − M, lalu t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"B = 3.723.000 − 3.650.000 = 73.000. t = (73.000 × 100) ÷ (3.650.000 × 10) = 0,2 tahun. Ubah ke hari: 0,2 × 365 = 73 hari. Jadi lama menabung 73 hari."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 3.650.000 × (10/100) × (73/365) = Rp73.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":0.2,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam hari. Ubah hasil dalam tahun ke hari."},{"jenis":"PERSEN","nilai":0.73,"pesan":"Ingat, suku bunga 10% ditulis p/100 = 10/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":1825,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":3723,"pesan":"Pada soal, Rp3.723.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M6-T1-01', 'M6', 1, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Gita menabung Rp900.000 di koperasi sekolah untuk membeli sepatu. Suku bunganya 10% per tahun. Berapa jumlah tabungan akhir Gita setelah 1 tahun?', '["Rp900.000","10% per tahun","1 tahun"]'::jsonb, '{"modal":900000,"suku_bunga":10,"lama":1,"satuan_lama":"tahun"}'::jsonb, 'tabungan_akhir', 'rupiah', 990000, 1, '["Diketahui: modal awal M = Rp900.000, suku bunga p = 10 (10% per tahun), lama menabung 1 tahun. Yang ditanya: jumlah tabungan akhir (A).","Gunakan rumus B = M × (p/100) × t, lalu A = M + B.","Lalu masukkan M = 900.000 dan p = 10 ke rumus B = M × (p/100) × t. Setelah B didapat, tambahkan ke modal awal."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp900.000, suku bunga p = 10 (10% per tahun), lama menabung 1 tahun. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"t = 1 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 900.000 × (10/100) × 1 = 90.000. A = 900.000 + 90.000 = 990.000. Jadi jumlah tabungan akhir Rp990.000."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp90.000 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"PERSEN","nilai":9900000,"pesan":"Ingat, suku bunga 10% ditulis p/100 = 10/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":90000,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M6-T1-02', 'M6', 1, 'latihan', 'isian', null, null, 'koperasi sekolah', 'Vina menabung Rp1.000.000 di koperasi sekolah dengan suku bunga 6% per tahun. Berapa besar bunga yang Vina peroleh setelah 6 bulan?', '["Rp1.000.000","6% per tahun","6 bulan"]'::jsonb, '{"modal":1000000,"suku_bunga":6,"lama":6,"satuan_lama":"bulan"}'::jsonb, 'bunga', 'rupiah', 30000, 1, '["Diketahui: modal awal M = Rp1.000.000, suku bunga p = 6 (6% per tahun), lama menabung 6 bulan. Yang ditanya: besar bunga (B).","Gunakan rumus B = M × (p/100) × t. Ingat, t harus dalam tahun.","Ubah dulu 6 bulan menjadi tahun: t = 6/12. Lalu masukkan M = 1.000.000 dan p = 6 ke rumus B = M × (p/100) × t."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.000.000, suku bunga p = 6 (6% per tahun), lama menabung 6 bulan. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 6/12 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 1.000.000 × (6/100) × (6/12) = 30.000. Jadi besar bunga Rp30.000."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp60.000. Lama menabung kurang dari 1 tahun, jadi bunganya lebih kecil. Rp30.000 masuk akal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":360000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 6 bulan = 6/12 tahun."},{"jenis":"PERSEN","nilai":3000000,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":1030000,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M6-T2-01', 'M6', 2, 'latihan', 'isian', null, null, 'bank', 'Wahyu ingin membeli sepeda seharga Rp2.090.000. Ia menabung Rp2.000.000 di bank dengan suku bunga 6% per tahun. Setelah berapa bulan jumlah tabungannya tepat cukup untuk membeli sepeda?', '["Rp2.000.000","6% per tahun","Rp2.090.000"]'::jsonb, '{"modal":2000000,"suku_bunga":6,"tabungan_akhir":2090000}'::jsonb, 'lama', 'bulan', 9, 0.01, '["Diketahui: modal awal M = Rp2.000.000, suku bunga p = 6 (6% per tahun), jumlah tabungan akhir (A) = Rp2.090.000. Yang ditanya: lama menabung (dalam bulan).","Gunakan rumus B = A − M, lalu t = (B × 100) ÷ (M × p). Hasil t dalam tahun, lalu ubah ke bulan.","Cari besar bunga dulu: B = 2.090.000 − 2.000.000. Kalikan besar bunga dengan 100, lalu bagi dengan M × p = 2.000.000 × 6."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.000.000, suku bunga p = 6 (6% per tahun), jumlah tabungan akhir (A) = Rp2.090.000. Ditanya: lama menabung (dalam bulan)."},{"langkah":"Rencanakan","isi":"Rumus: B = A − M, lalu t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"B = 2.090.000 − 2.000.000 = 90.000. t = (90.000 × 100) ÷ (2.000.000 × 6) = 0,75 tahun. Ubah ke bulan: 0,75 × 12 = 9 bulan. Jadi lama menabung 9 bulan."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.000.000 × (6/100) × (9/12) = Rp90.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":0.75,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam bulan. Ubah hasil dalam tahun ke bulan."},{"jenis":"PERSEN","nilai":0.09,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":16,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":209,"pesan":"Pada soal, Rp2.090.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M6-T2-02', 'M6', 2, 'latihan', 'isian', null, null, 'koperasi', 'Yoga ingin punya Rp1.300.000 untuk membeli tas sekolah setelah menabung 6 bulan. Suku bunga di koperasi 8% per tahun. Berapa modal awal yang harus Yoga tabung sekarang?', '["8% per tahun","6 bulan","Rp1.300.000"]'::jsonb, '{"tabungan_akhir":1300000,"suku_bunga":8,"lama":6,"satuan_lama":"bulan"}'::jsonb, 'modal', 'rupiah', 1250000, 1, '["Diketahui: suku bunga p = 8 (8% per tahun), lama menabung 6 bulan, jumlah tabungan akhir (A) = Rp1.300.000. Yang ditanya: modal awal (M).","Gunakan rumus M = A ÷ (1 + (p/100) × t). Ingat, t harus dalam tahun.","Ubah dulu 6 bulan menjadi tahun: t = 6/12. Hitung dulu (p/100) × t = (8/100) × (6/12). Lalu bagi jumlah tabungan akhir dengan (1 + hasil itu)."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui suku bunga p = 8 (8% per tahun), lama menabung 6 bulan, jumlah tabungan akhir (A) = Rp1.300.000. Ditanya: modal awal (M)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 6/12 tahun. Rumus: M = A ÷ (1 + (p/100) × t)."},{"langkah":"Hitung","isi":"(p/100) × t = (8/100) × (6/12) = 0,04. M = 1.300.000 ÷ (1 + 0,04) = 1.250.000. Jadi modal awal Rp1.250.000."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 1.250.000 × (8/100) × (6/12) = Rp50.000, dan M + B = Rp1.300.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":32500000,"pesan":"Pada soal, Rp1.300.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Karena A = M + B, modal awal M = A ÷ (1 + (p/100) × t)."},{"jenis":"RUMUS_INVERS","nilai":1248000,"pesan":"Bunga dihitung dari modal awal, bukan dari jumlah tabungan akhir. Gunakan M = A ÷ (1 + (p/100) × t)."},{"jenis":"SATUAN_WAKTU","nilai":878378.3784,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 6 bulan = 6/12 tahun."},{"jenis":"PERSEN","nilai":260000,"pesan":"Ingat, suku bunga 8% ditulis p/100 = 8/100 di dalam rumus."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M6-T2-03', 'M6', 2, 'latihan', 'isian', null, null, 'bank', 'Zahra menabung Rp1.800.000 di bank untuk membeli ponsel. Suku bunganya 6% per tahun. Berapa jumlah tabungan akhir Zahra setelah 8 bulan?', '["Rp1.800.000","6% per tahun","8 bulan"]'::jsonb, '{"modal":1800000,"suku_bunga":6,"lama":8,"satuan_lama":"bulan"}'::jsonb, 'tabungan_akhir', 'rupiah', 1872000, 1, '["Diketahui: modal awal M = Rp1.800.000, suku bunga p = 6 (6% per tahun), lama menabung 8 bulan. Yang ditanya: jumlah tabungan akhir (A).","Gunakan rumus B = M × (p/100) × t, lalu A = M + B. Ingat, t harus dalam tahun.","Ubah dulu 8 bulan menjadi tahun: t = 8/12. Lalu masukkan M = 1.800.000 dan p = 6 ke rumus B = M × (p/100) × t. Setelah B didapat, tambahkan ke modal awal."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.800.000, suku bunga p = 6 (6% per tahun), lama menabung 8 bulan. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 8/12 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 1.800.000 × (6/100) × (8/12) = 72.000. A = 1.800.000 + 72.000 = 1.872.000. Jadi jumlah tabungan akhir Rp1.872.000."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp72.000 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":2664000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 8 bulan = 8/12 tahun."},{"jenis":"PERSEN","nilai":9000000,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":72000,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M6-T3-01', 'M6', 3, 'latihan', 'isian', null, null, 'bank', 'Rani ingin membeli laptop seharga Rp3.766.800. Ia menabung Rp3.650.000 di bank dengan suku bunga 8% per tahun. Setelah berapa hari jumlah tabungannya tepat cukup untuk membeli laptop?', '["Rp3.650.000","8% per tahun","Rp3.766.800"]'::jsonb, '{"modal":3650000,"suku_bunga":8,"tabungan_akhir":3766800}'::jsonb, 'lama', 'hari', 146, 0.01, '["Diketahui: modal awal M = Rp3.650.000, suku bunga p = 8 (8% per tahun), jumlah tabungan akhir (A) = Rp3.766.800. Yang ditanya: lama menabung (dalam hari).","Gunakan rumus B = A − M, lalu t = (B × 100) ÷ (M × p). Hasil t dalam tahun, lalu ubah ke hari.","Cari besar bunga dulu: B = 3.766.800 − 3.650.000. Kalikan besar bunga dengan 100, lalu bagi dengan M × p = 3.650.000 × 8."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp3.650.000, suku bunga p = 8 (8% per tahun), jumlah tabungan akhir (A) = Rp3.766.800. Ditanya: lama menabung (dalam hari)."},{"langkah":"Rencanakan","isi":"Rumus: B = A − M, lalu t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"B = 3.766.800 − 3.650.000 = 116.800. t = (116.800 × 100) ÷ (3.650.000 × 8) = 0,4 tahun. Ubah ke hari: 0,4 × 365 = 146 hari. Jadi lama menabung 146 hari."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 3.650.000 × (8/100) × (146/365) = Rp116.800. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":0.4,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam hari. Ubah hasil dalam tahun ke hari."},{"jenis":"PERSEN","nilai":1.46,"pesan":"Ingat, suku bunga 8% ditulis p/100 = 8/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":912.5,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":4708.5,"pesan":"Pada soal, Rp3.766.800 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M6-T3-02', 'M6', 3, 'latihan', 'isian', null, null, 'koperasi', 'Budi ingin punya Rp4.450.000 untuk membeli kamera setelah menabung 18 bulan. Suku bunga di koperasi 7,5% per tahun. Berapa modal awal yang harus Budi tabung sekarang?', '["7,5% per tahun","18 bulan","Rp4.450.000"]'::jsonb, '{"tabungan_akhir":4450000,"suku_bunga":7.5,"lama":18,"satuan_lama":"bulan"}'::jsonb, 'modal', 'rupiah', 4000000, 1, '["Diketahui: suku bunga p = 7,5 (7,5% per tahun), lama menabung 18 bulan, jumlah tabungan akhir (A) = Rp4.450.000. Yang ditanya: modal awal (M).","Gunakan rumus M = A ÷ (1 + (p/100) × t). Ingat, t harus dalam tahun.","Ubah dulu 18 bulan menjadi tahun: t = 18/12. Hitung dulu (p/100) × t = (7,5/100) × (18/12). Lalu bagi jumlah tabungan akhir dengan (1 + hasil itu)."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui suku bunga p = 7,5 (7,5% per tahun), lama menabung 18 bulan, jumlah tabungan akhir (A) = Rp4.450.000. Ditanya: modal awal (M)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 18/12 tahun. Rumus: M = A ÷ (1 + (p/100) × t)."},{"langkah":"Hitung","isi":"(p/100) × t = (7,5/100) × (18/12) = 0,11. M = 4.450.000 ÷ (1 + 0,11) = 4.000.000. Jadi modal awal Rp4.000.000."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 4.000.000 × (7,5/100) × (18/12) = Rp450.000, dan M + B = Rp4.450.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":39555555.5556,"pesan":"Pada soal, Rp4.450.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Karena A = M + B, modal awal M = A ÷ (1 + (p/100) × t)."},{"jenis":"RUMUS_INVERS","nilai":3949375,"pesan":"Bunga dihitung dari modal awal, bukan dari jumlah tabungan akhir. Gunakan M = A ÷ (1 + (p/100) × t)."},{"jenis":"SATUAN_WAKTU","nilai":1893617.0213,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 18 bulan = 18/12 tahun."},{"jenis":"PERSEN","nilai":363265.3061,"pesan":"Ingat, suku bunga 7,5% ditulis p/100 = 7,5/100 di dalam rumus."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('M6-T3-03', 'M6', 3, 'latihan', 'isian', null, null, 'bank desa', 'Sinta ingin membeli gitar seharga Rp2.580.000. Ia menabung Rp2.400.000 di bank desa dengan suku bunga 6% per tahun. Setelah berapa bulan jumlah tabungannya tepat cukup untuk membeli gitar?', '["Rp2.400.000","6% per tahun","Rp2.580.000"]'::jsonb, '{"modal":2400000,"suku_bunga":6,"tabungan_akhir":2580000}'::jsonb, 'lama', 'bulan', 15, 0.01, '["Diketahui: modal awal M = Rp2.400.000, suku bunga p = 6 (6% per tahun), jumlah tabungan akhir (A) = Rp2.580.000. Yang ditanya: lama menabung (dalam bulan).","Gunakan rumus B = A − M, lalu t = (B × 100) ÷ (M × p). Hasil t dalam tahun, lalu ubah ke bulan.","Cari besar bunga dulu: B = 2.580.000 − 2.400.000. Kalikan besar bunga dengan 100, lalu bagi dengan M × p = 2.400.000 × 6."]'::jsonb, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.400.000, suku bunga p = 6 (6% per tahun), jumlah tabungan akhir (A) = Rp2.580.000. Ditanya: lama menabung (dalam bulan)."},{"langkah":"Rencanakan","isi":"Rumus: B = A − M, lalu t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"B = 2.580.000 − 2.400.000 = 180.000. t = (180.000 × 100) ÷ (2.400.000 × 6) = 1,25 tahun. Ubah ke bulan: 1,25 × 12 = 15 bulan. Jadi lama menabung 15 bulan."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.400.000 × (6/100) × (15/12) = Rp180.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":1.25,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam bulan. Ubah hasil dalam tahun ke bulan."},{"jenis":"PERSEN","nilai":0.15,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":9.6,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":215,"pesan":"Pada soal, Rp2.580.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('KU-KONSEP-T1-PG-01', 'M1', 1, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Uang yang pertama kali ditabung","nilai":null,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"Tambahan uang dari bank atau koperasi","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o3","teks":"Uang di tabungan setelah ditambah bunga","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o4","teks":"Persen bunga dalam satu tahun","nilai":null,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'konsep', 'konsep', 'Pada soal tabungan, apa arti modal awal (M)?', '[]'::jsonb, '{}'::jsonb, 'bunga', 'rupiah', null, null, null, '[{"langkah":"Pahami","isi":"Pertanyaan ini menanyakan arti simbol M."},{"langkah":"Rencanakan","isi":"Ingat lima istilah: M modal awal, B besar bunga, p suku bunga per tahun, t lama menabung, A jumlah tabungan akhir."},{"langkah":"Hitung","isi":"M adalah uang yang pertama kali ditabung, sebelum ada bunga."},{"langkah":"Periksa","isi":"Tambahan uang adalah B, dan uang setelah ditambah bunga adalah jumlah tabungan akhir (A). Jadi jawabannya tepat."}]'::jsonb, '[]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('KU-KONSEP-T1-PG-02', 'M1', 1, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"p = 6, lalu dibagi 100 menjadi (6/100)","nilai":null,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"p = 0,6","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o3","teks":"p = 60","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o4","teks":"p = 6, tanpa dibagi 100","nilai":null,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'konsep', 'konsep', 'Suku bunga sebuah koperasi 6% per tahun. Bagaimana suku bunga ini dimasukkan ke rumus B = M × (p/100) × t?', '[]'::jsonb, '{}'::jsonb, 'bunga', 'rupiah', null, null, null, '[{"langkah":"Pahami","isi":"Yang ditanya: cara menulis suku bunga 6% di rumus."},{"langkah":"Rencanakan","isi":"Di rumus, suku bunga ditulis sebagai angka persennya (p = 6), lalu dibagi 100."},{"langkah":"Hitung","isi":"6% = 6/100 = 0,06, jadi bagian rumusnya (p/100) = (6/100)."},{"langkah":"Periksa","isi":"Jika p tidak dibagi 100, bunganya menjadi 100 kali terlalu besar. Jadi jawabannya tepat."}]'::jsonb, '[]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('KU-KONSEP-T1-PG-03', 'M1', 1, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Dari modal awal saja","nilai":null,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"Dari jumlah tabungan akhir tahun sebelumnya","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o3","teks":"Dari bunga tahun sebelumnya","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o4","teks":"Dari suku bunga saja, tanpa modal","nilai":null,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'konsep', 'konsep', 'Pada bunga tunggal, bunga setiap tahun dihitung dari apa?', '[]'::jsonb, '{}'::jsonb, 'bunga', 'rupiah', null, null, null, '[{"langkah":"Pahami","isi":"Yang ditanya: dasar perhitungan bunga tunggal."},{"langkah":"Rencanakan","isi":"Rumus bunga tunggal B = M × (p/100) × t hanya memakai modal awal M."},{"langkah":"Hitung","isi":"Karena dasarnya selalu M, bunga setiap tahun sama besar."},{"langkah":"Periksa","isi":"Jika bunga dihitung dari tabungan akhir tahun sebelumnya, itu bukan bunga tunggal. Jadi jawabannya tepat."}]'::jsonb, '[]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('KU-KONSEP-T1-PG-04', 'M1', 1, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Modal awal ditambah besar bunga","nilai":null,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"Modal awal dikurangi besar bunga","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o3","teks":"Besar bunga saja","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o4","teks":"Modal awal dikali suku bunga","nilai":null,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'konsep', 'konsep', 'Apa yang dimaksud dengan jumlah tabungan akhir (A)?', '[]'::jsonb, '{}'::jsonb, 'bunga', 'rupiah', null, null, null, '[{"langkah":"Pahami","isi":"Yang ditanya: arti jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"Rumusnya A = M + B."},{"langkah":"Hitung","isi":"Jadi jumlah tabungan akhir = modal awal + besar bunga."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir selalu lebih besar dari modal awal jika ada bunga. Jadi jawabannya tepat."}]'::jsonb, '[]'::jsonb)
on conflict (kode) do nothing;

