values ('KU-KONSEP-T2-PG-01', 'M1', 2, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"t = 8/12","nilai":null,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"t = 8","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o3","teks":"t = 8/365","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o4","teks":"t = 12/8","nilai":null,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'konsep', 'konsep', 'Lama menabung 8 bulan. Nilai t yang dimasukkan ke rumus B = M × (p/100) × t adalah ....', '[]'::jsonb, '{}'::jsonb, 'bunga', 'rupiah', null, null, null, '[{"langkah":"Pahami","isi":"Yang ditanya: nilai t untuk lama menabung 8 bulan."},{"langkah":"Rencanakan","isi":"Suku bunga per tahun, jadi t harus dalam tahun. 1 tahun = 12 bulan."},{"langkah":"Hitung","isi":"t = banyak bulan ÷ 12 = 8/12 tahun."},{"langkah":"Periksa","isi":"Memakai t = 8 membuat bunga 12 kali terlalu besar. Jadi jawabannya tepat."}]'::jsonb, '[]'::jsonb)
on conflict (kode) do nothing;

