values ('KU-KONSEP-T2-PG-02', 'M1', 2, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Bunganya bertambah Rp100.000 setiap tahun","nilai":null,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"Bunga tahun kedua lebih besar daripada bunga tahun pertama","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o3","teks":"Bunga tahun kedua Rp110.000","nilai":null,"kunci":false,"jenis_kesalahan":null},{"id":"o4","teks":"Bunga hanya diberikan pada tahun pertama","nilai":null,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'konsep', 'konsep', 'Modal awal Rp1.000.000 dengan suku bunga 10% per tahun (bunga tunggal). Pernyataan mana yang benar?', '[]'::jsonb, '{}'::jsonb, 'bunga', 'rupiah', null, null, null, '[{"langkah":"Pahami","isi":"Yang ditanya: sifat bunga tunggal untuk M = Rp1.000.000 dan p = 10."},{"langkah":"Rencanakan","isi":"Bunga 1 tahun = M × (p/100) × 1."},{"langkah":"Hitung","isi":"B = 1.000.000 × (10/100) × 1 = Rp100.000 setiap tahun."},{"langkah":"Periksa","isi":"Pada bunga tunggal, bunga dihitung dari modal awal saja, jadi bunga setiap tahun sama. Jadi jawabannya tepat."}]'::jsonb, '[]'::jsonb)
on conflict (kode) do nothing;

insert into public.soal (kode, sub_materi, tingkat, bank, bentuk, opsi, kategori_kuis, konteks, teks_soal, sorotan, diketahui, ditanya, satuan_jawaban, jawaban, toleransi, petunjuk, pembahasan, pola_kesalahan)
values ('KU-BUNGA-T1-PG-01', 'M2', 1, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Rp200.000","nilai":200000,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"Rp20.000.000","nilai":20000000,"kunci":false,"jenis_kesalahan":"PERSEN"},{"id":"o3","teks":"Rp2.200.000","nilai":2200000,"kunci":false,"jenis_kesalahan":"TERTUKAR_BUNGA_TABUNGAN"},{"id":"o4","teks":"Rp100.000","nilai":100000,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'besar_bunga', 'bank', 'Joko menabung Rp2.000.000 di bank dengan suku bunga 5% per tahun. Berapa besar bunga yang Joko peroleh setelah 2 tahun?', '["Rp2.000.000","5% per tahun","2 tahun"]'::jsonb, '{"modal":2000000,"suku_bunga":5,"lama":2,"satuan_lama":"tahun"}'::jsonb, 'bunga', 'rupiah', 200000, 1, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.000.000, suku bunga p = 5 (5% per tahun), lama menabung 2 tahun. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"t = 2 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 2.000.000 × (5/100) × 2 = 200.000. Jadi besar bunga Rp200.000."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp100.000. Untuk 2 tahun, bunganya 2 × Rp100.000 = Rp200.000. Cocok."}]'::jsonb, '[{"jenis":"PERSEN","nilai":20000000,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":2200000,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
on conflict (kode) do nothing;

