values ('KU-BUNGA-T1-PG-02', 'M2', 1, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Rp9.600.000","nilai":9600000,"kunci":false,"jenis_kesalahan":"PERSEN"},{"id":"o2","teks":"Rp96.000","nilai":96000,"kunci":true,"jenis_kesalahan":null},{"id":"o3","teks":"Rp1.296.000","nilai":1296000,"kunci":false,"jenis_kesalahan":"TERTUKAR_BUNGA_TABUNGAN"},{"id":"o4","teks":"Rp192.000","nilai":192000,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'besar_bunga', 'koperasi', 'Maya menabung Rp1.200.000 di koperasi dengan suku bunga 8% per tahun. Berapa besar bunga yang Maya peroleh setelah 1 tahun?', '["Rp1.200.000","8% per tahun","1 tahun"]'::jsonb, '{"modal":1200000,"suku_bunga":8,"lama":1,"satuan_lama":"tahun"}'::jsonb, 'bunga', 'rupiah', 96000, 1, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.200.000, suku bunga p = 8 (8% per tahun), lama menabung 1 tahun. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"t = 1 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 1.200.000 × (8/100) × 1 = 96.000. Jadi besar bunga Rp96.000."},{"langkah":"Periksa","isi":"Bunga 1 tahun adalah 8% dari modal awal, yaitu Rp96.000. Cocok."}]'::jsonb, '[{"jenis":"PERSEN","nilai":9600000,"pesan":"Ingat, suku bunga 8% ditulis p/100 = 8/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":1296000,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
