values ('KU-AKHIR-T1-PG-01', 'M4', 1, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Rp17.000.000","nilai":17000000,"kunci":false,"jenis_kesalahan":"PERSEN"},{"id":"o2","teks":"Rp160.000","nilai":160000,"kunci":false,"jenis_kesalahan":"TERTUKAR_BUNGA_TABUNGAN"},{"id":"o3","teks":"Rp1.160.000","nilai":1160000,"kunci":true,"jenis_kesalahan":null},{"id":"o4","teks":"Rp80.000","nilai":80000,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'tabungan_akhir', 'bank desa', 'Raka menabung Rp1.000.000 di bank desa dengan suku bunga 8% per tahun. Berapa jumlah tabungan Raka setelah 2 tahun?', '["Rp1.000.000","8% per tahun","2 tahun"]'::jsonb, '{"modal":1000000,"suku_bunga":8,"lama":2,"satuan_lama":"tahun"}'::jsonb, 'tabungan_akhir', 'rupiah', 1160000, 1, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.000.000, suku bunga p = 8 (8% per tahun), lama menabung 2 tahun. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"t = 2 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 1.000.000 × (8/100) × 2 = 160.000. A = 1.000.000 + 160.000 = 1.160.000. Jadi jumlah tabungan akhir Rp1.160.000."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp160.000 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"PERSEN","nilai":17000000,"pesan":"Ingat, suku bunga 8% ditulis p/100 = 8/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":160000,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
on conflict (kode) do nothing;

