values ('KU-MODALP-T1-PG-01', 'M5', 1, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"5% per tahun","nilai":5,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"0,05% per tahun","nilai":0.05,"kunci":false,"jenis_kesalahan":"PERSEN"},{"id":"o3","teks":"10% per tahun","nilai":10,"kunci":false,"jenis_kesalahan":"RUMUS_INVERS"},{"id":"o4","teks":"2,5% per tahun","nilai":2.5,"kunci":false,"jenis_kesalahan":null}]'::jsonb, 'modal_suku_bunga', 'bank', 'Tono menabung Rp2.000.000 di bank. Setelah 2 tahun, ia mendapat bunga Rp200.000. Berapa suku bunga per tahunnya?', '["Rp2.000.000","2 tahun","Rp200.000"]'::jsonb, '{"modal":2000000,"bunga":200000,"lama":2,"satuan_lama":"tahun"}'::jsonb, 'suku_bunga', 'persen', 5, 0.01, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.000.000, lama menabung 2 tahun, besar bunga B = Rp200.000. Ditanya: suku bunga per tahun (p)."},{"langkah":"Rencanakan","isi":"t = 2 tahun. Rumus: p = (B × 100) ÷ (M × t)."},{"langkah":"Hitung","isi":"p = (200.000 × 100) ÷ (2.000.000 × 2) = 5. Jadi suku bunganya 5% per tahun."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 2.000.000 × (5/100) × 2 = Rp200.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"PERSEN","nilai":0.05,"pesan":"Hasil baginya masih berupa pecahan. Kalikan dengan 100 agar menjadi persen: p = (B × 100) ÷ (M × t)."},{"jenis":"RUMUS_INVERS","nilai":10,"pesan":"Untuk mencari suku bunga, gunakan p = (B × 100) ÷ (M × t). Jangan lupa membagi dengan lama menabung."}]'::jsonb)
on conflict (kode) do nothing;

