values ('KU-BUNGA-T2-PG-04', 'M3', 2, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Rp432.000","nilai":432000,"kunci":false,"jenis_kesalahan":"SATUAN_WAKTU"},{"id":"o2","teks":"Rp3.600.000","nilai":3600000,"kunci":false,"jenis_kesalahan":"PERSEN"},{"id":"o3","teks":"Rp1.236.000","nilai":1236000,"kunci":false,"jenis_kesalahan":"TERTUKAR_BUNGA_TABUNGAN"},{"id":"o4","teks":"Rp36.000","nilai":36000,"kunci":true,"jenis_kesalahan":null}]'::jsonb, 'besar_bunga', 'koperasi sekolah', 'Budi menabung Rp1.200.000 di koperasi sekolah dengan suku bunga 9% per tahun. Berapa besar bunga yang Budi peroleh setelah 4 bulan?', '["Rp1.200.000","9% per tahun","4 bulan"]'::jsonb, '{"modal":1200000,"suku_bunga":9,"lama":4,"satuan_lama":"bulan"}'::jsonb, 'bunga', 'rupiah', 36000, 1, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.200.000, suku bunga p = 9 (9% per tahun), lama menabung 4 bulan. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 4/12 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 1.200.000 × (9/100) × (4/12) = 36.000. Jadi besar bunga Rp36.000."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp108.000. Lama menabung kurang dari 1 tahun, jadi bunganya lebih kecil. Rp36.000 masuk akal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":432000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 4 bulan = 4/12 tahun."},{"jenis":"PERSEN","nilai":3600000,"pesan":"Ingat, suku bunga 9% ditulis p/100 = 9/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":1236000,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
on conflict (kode) do nothing;

