values ('KU-TERAP-T2-PG-01', 'M6', 2, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"0,5 bulan","nilai":0.5,"kunci":false,"jenis_kesalahan":"SATUAN_WAKTU"},{"id":"o2","teks":"0,06 bulan","nilai":0.06,"kunci":false,"jenis_kesalahan":"PERSEN"},{"id":"o3","teks":"6 bulan","nilai":6,"kunci":true,"jenis_kesalahan":null},{"id":"o4","teks":"24 bulan","nilai":24,"kunci":false,"jenis_kesalahan":"RUMUS_INVERS"}]'::jsonb, 'penerapan', 'koperasi sekolah', 'Nina ingin membeli sepeda seharga Rp1.260.000. Ia menabung Rp1.200.000 di koperasi sekolah dengan suku bunga 10% per tahun. Setelah berapa bulan jumlah tabungannya tepat cukup untuk membeli sepeda?', '["Rp1.200.000","10% per tahun","Rp1.260.000"]'::jsonb, '{"modal":1200000,"suku_bunga":10,"tabungan_akhir":1260000}'::jsonb, 'lama', 'bulan', 6, 0.01, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.200.000, suku bunga p = 10 (10% per tahun), jumlah tabungan akhir (A) = Rp1.260.000. Ditanya: lama menabung (dalam bulan)."},{"langkah":"Rencanakan","isi":"Rumus: B = A − M, lalu t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"B = 1.260.000 − 1.200.000 = 60.000. t = (60.000 × 100) ÷ (1.200.000 × 10) = 0,5 tahun. Ubah ke bulan: 0,5 × 12 = 6 bulan. Jadi lama menabung 6 bulan."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 1.200.000 × (10/100) × (6/12) = Rp60.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":0.5,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam bulan. Ubah hasil dalam tahun ke bulan."},{"jenis":"PERSEN","nilai":0.06,"pesan":"Ingat, suku bunga 10% ditulis p/100 = 10/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":24,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":126,"pesan":"Pada soal, Rp1.260.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
