values ('KU-MODALP-T3-PG-01', 'M5', 3, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"Rp3.000.000","nilai":3000000,"kunci":true,"jenis_kesalahan":null},{"id":"o2","teks":"Rp53.000.000","nilai":53000000,"kunci":false,"jenis_kesalahan":"TERTUKAR_BUNGA_TABUNGAN"},{"id":"o3","teks":"Rp2.989.200","nilai":2989200,"kunci":false,"jenis_kesalahan":"RUMUS_INVERS"},{"id":"o4","teks":"Rp1.848.837","nilai":1848837,"kunci":false,"jenis_kesalahan":"SATUAN_WAKTU"}]'::jsonb, 'modal_suku_bunga', 'bank desa', 'Setelah menabung 9 bulan di bank desa dengan suku bunga 8% per tahun, jumlah tabungan Gita menjadi Rp3.180.000. Berapa modal awal Gita?', '["8% per tahun","9 bulan","Rp3.180.000"]'::jsonb, '{"tabungan_akhir":3180000,"suku_bunga":8,"lama":9,"satuan_lama":"bulan"}'::jsonb, 'modal', 'rupiah', 3000000, 1, null, '[{"langkah":"Pahami","isi":"Diketahui suku bunga p = 8 (8% per tahun), lama menabung 9 bulan, jumlah tabungan akhir (A) = Rp3.180.000. Ditanya: modal awal (M)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 9/12 tahun. Rumus: M = A ÷ (1 + (p/100) × t)."},{"langkah":"Hitung","isi":"(p/100) × t = (8/100) × (9/12) = 0,06. M = 3.180.000 ÷ (1 + 0,06) = 3.000.000. Jadi modal awal Rp3.000.000."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 3.000.000 × (8/100) × (9/12) = Rp180.000, dan M + B = Rp3.180.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":53000000,"pesan":"Pada soal, Rp3.180.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Karena A = M + B, modal awal M = A ÷ (1 + (p/100) × t)."},{"jenis":"RUMUS_INVERS","nilai":2989200,"pesan":"Bunga dihitung dari modal awal, bukan dari jumlah tabungan akhir. Gunakan M = A ÷ (1 + (p/100) × t)."},{"jenis":"SATUAN_WAKTU","nilai":1848837.2093,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 9 bulan = 9/12 tahun."},{"jenis":"PERSEN","nilai":454285.7143,"pesan":"Ingat, suku bunga 8% ditulis p/100 = 8/100 di dalam rumus."}]'::jsonb)
on conflict (kode) do nothing;

