values ('KU-MODALP-T3-PG-02', 'M5', 3, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"0,06% per tahun","nilai":0.06,"kunci":false,"jenis_kesalahan":"PERSEN"},{"id":"o2","teks":"6% per tahun","nilai":6,"kunci":true,"jenis_kesalahan":null},{"id":"o3","teks":"0,02% per tahun","nilai":0.02,"kunci":false,"jenis_kesalahan":"SATUAN_WAKTU"},{"id":"o4","teks":"1,2% per tahun","nilai":1.2,"kunci":false,"jenis_kesalahan":"RUMUS_INVERS"}]'::jsonb, 'modal_suku_bunga', 'bank', 'Hadi menabung Rp3.650.000 di bank. Setelah 73 hari, jumlah tabungannya menjadi Rp3.693.800. Berapa suku bunga per tahunnya?', '["Rp3.650.000","73 hari","Rp3.693.800"]'::jsonb, '{"modal":3650000,"tabungan_akhir":3693800,"lama":73,"satuan_lama":"hari"}'::jsonb, 'suku_bunga', 'persen', 6, 0.01, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp3.650.000, lama menabung 73 hari, jumlah tabungan akhir (A) = Rp3.693.800. Ditanya: suku bunga per tahun (p)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam hari, jadi t = 73/365 tahun. Rumus: B = A − M, lalu p = (B × 100) ÷ (M × t)."},{"langkah":"Hitung","isi":"B = 3.693.800 − 3.650.000 = 43.800. p = (43.800 × 100) ÷ (3.650.000 × (73/365)) = 6. Jadi suku bunganya 6% per tahun."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 3.650.000 × (6/100) × (73/365) = Rp43.800. Sama dengan soal."}]'::jsonb, '[{"jenis":"PERSEN","nilai":0.06,"pesan":"Hasil baginya masih berupa pecahan. Kalikan dengan 100 agar menjadi persen: p = (B × 100) ÷ (M × t)."},{"jenis":"SATUAN_WAKTU","nilai":0.0164,"pesan":"Lama menabung dalam hari. Ubah dulu ke tahun: 73 hari = 73/365 tahun."},{"jenis":"RUMUS_INVERS","nilai":1.2,"pesan":"Untuk mencari suku bunga, gunakan p = (B × 100) ÷ (M × t). Jangan lupa membagi dengan lama menabung."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":506,"pesan":"Pada soal, Rp3.693.800 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
on conflict (kode) do nothing;

