values ('KU-TERAP-T3-PG-01', 'M6', 3, 'kuis', 'pilihan_ganda', '[{"id":"o1","teks":"0,4 hari","nilai":0.4,"kunci":false,"jenis_kesalahan":"SATUAN_WAKTU"},{"id":"o2","teks":"1,46 hari","nilai":1.46,"kunci":false,"jenis_kesalahan":"PERSEN"},{"id":"o3","teks":"146 hari","nilai":146,"kunci":true,"jenis_kesalahan":null},{"id":"o4","teks":"912,5 hari","nilai":912.5,"kunci":false,"jenis_kesalahan":"RUMUS_INVERS"}]'::jsonb, 'penerapan', 'bank', 'Intan ingin membeli laptop seharga Rp7.446.000. Ia menabung Rp7.300.000 di bank dengan suku bunga 5% per tahun. Setelah berapa hari jumlah tabungannya tepat cukup untuk membeli laptop?', '["Rp7.300.000","5% per tahun","Rp7.446.000"]'::jsonb, '{"modal":7300000,"suku_bunga":5,"tabungan_akhir":7446000}'::jsonb, 'lama', 'hari', 146, 0.01, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp7.300.000, suku bunga p = 5 (5% per tahun), jumlah tabungan akhir (A) = Rp7.446.000. Ditanya: lama menabung (dalam hari)."},{"langkah":"Rencanakan","isi":"Rumus: B = A − M, lalu t = (B × 100) ÷ (M × p)."},{"langkah":"Hitung","isi":"B = 7.446.000 − 7.300.000 = 146.000. t = (146.000 × 100) ÷ (7.300.000 × 5) = 0,4 tahun. Ubah ke hari: 0,4 × 365 = 146 hari. Jadi lama menabung 146 hari."},{"langkah":"Periksa","isi":"Masukkan kembali: B = 7.300.000 × (5/100) × (146/365) = Rp146.000. Sama dengan soal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":0.4,"pesan":"Perhatikan satuan yang ditanya. Jawaban diminta dalam hari. Ubah hasil dalam tahun ke hari."},{"jenis":"PERSEN","nilai":1.46,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"RUMUS_INVERS","nilai":912.5,"pesan":"Untuk mencari lama menabung, gunakan t = (B × 100) ÷ (M × p), jangan dibalik."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":7446,"pesan":"Pada soal, Rp7.446.000 adalah jumlah tabungan akhir (A), bukan besar bunga. Cari bunganya dulu: B = A − M."}]'::jsonb)
on conflict (kode) do nothing;

