values ('KU-BUNGA-T3-IS-01', 'M3', 3, 'kuis', 'isian', null, 'besar_bunga', 'bank', 'Raka menabung Rp2.190.000 di bank dengan suku bunga 10% per tahun. Berapa besar bunga yang Raka peroleh setelah 73 hari?', '["Rp2.190.000","10% per tahun","73 hari"]'::jsonb, '{"modal":2190000,"suku_bunga":10,"lama":73,"satuan_lama":"hari"}'::jsonb, 'bunga', 'rupiah', 43800, 1, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp2.190.000, suku bunga p = 10 (10% per tahun), lama menabung 73 hari. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam hari, jadi t = 73/365 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 2.190.000 × (10/100) × (73/365) = 43.800. Jadi besar bunga Rp43.800."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp219.000. Lama menabung kurang dari 1 tahun, jadi bunganya lebih kecil. Rp43.800 masuk akal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":15987000,"pesan":"Lama menabung dalam hari. Ubah dulu ke tahun: 73 hari = 73/365 tahun."},{"jenis":"PERSEN","nilai":4380000,"pesan":"Ingat, suku bunga 10% ditulis p/100 = 10/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":2233800,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
on conflict (kode) do nothing;

