values ('KU-BUNGA-T3-IS-02', 'M3', 3, 'kuis', 'isian', null, 'besar_bunga', 'bank desa', 'Salsa menabung Rp1.460.000 di bank desa dengan suku bunga 5% per tahun. Berapa besar bunga yang Salsa peroleh setelah 292 hari?', '["Rp1.460.000","5% per tahun","292 hari"]'::jsonb, '{"modal":1460000,"suku_bunga":5,"lama":292,"satuan_lama":"hari"}'::jsonb, 'bunga', 'rupiah', 58400, 1, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.460.000, suku bunga p = 5 (5% per tahun), lama menabung 292 hari. Ditanya: besar bunga (B)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam hari, jadi t = 292/365 tahun. Rumus: B = M × (p/100) × t."},{"langkah":"Hitung","isi":"B = 1.460.000 × (5/100) × (292/365) = 58.400. Jadi besar bunga Rp58.400."},{"langkah":"Periksa","isi":"Bunga 1 tahun = Rp73.000. Lama menabung kurang dari 1 tahun, jadi bunganya lebih kecil. Rp58.400 masuk akal."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":21316000,"pesan":"Lama menabung dalam hari. Ubah dulu ke tahun: 292 hari = 292/365 tahun."},{"jenis":"PERSEN","nilai":5840000,"pesan":"Ingat, suku bunga 5% ditulis p/100 = 5/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":1518400,"pesan":"Yang ditanya adalah besar bunga (B) saja. Jumlah tabungan akhir (A) = M + B, jadi bunganya jangan ditambah modal awal."}]'::jsonb)
