values ('KU-AKHIR-T3-IS-01', 'M4', 3, 'kuis', 'isian', null, 'tabungan_akhir', 'koperasi sekolah', 'Tono menabung Rp1.825.000 di koperasi sekolah dengan suku bunga 6% per tahun. Berapa jumlah tabungan Tono setelah 219 hari?', '["Rp1.825.000","6% per tahun","219 hari"]'::jsonb, '{"modal":1825000,"suku_bunga":6,"lama":219,"satuan_lama":"hari"}'::jsonb, 'tabungan_akhir', 'rupiah', 1890700, 1, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp1.825.000, suku bunga p = 6 (6% per tahun), lama menabung 219 hari. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam hari, jadi t = 219/365 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 1.825.000 × (6/100) × (219/365) = 65.700. A = 1.825.000 + 65.700 = 1.890.700. Jadi jumlah tabungan akhir Rp1.890.700."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp65.700 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":25805500,"pesan":"Lama menabung dalam hari. Ubah dulu ke tahun: 219 hari = 219/365 tahun."},{"jenis":"PERSEN","nilai":8395000,"pesan":"Ingat, suku bunga 6% ditulis p/100 = 6/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":65700,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
on conflict (kode) do nothing;

