values ('KU-AKHIR-T3-IS-02', 'M4', 3, 'kuis', 'isian', null, 'tabungan_akhir', 'bank', 'Umi menabung Rp4.800.000 di bank dengan suku bunga 7,5% per tahun. Berapa jumlah tabungan Umi setelah 15 bulan?', '["Rp4.800.000","7,5% per tahun","15 bulan"]'::jsonb, '{"modal":4800000,"suku_bunga":7.5,"lama":15,"satuan_lama":"bulan"}'::jsonb, 'tabungan_akhir', 'rupiah', 5250000, 1, null, '[{"langkah":"Pahami","isi":"Diketahui modal awal M = Rp4.800.000, suku bunga p = 7,5 (7,5% per tahun), lama menabung 15 bulan. Ditanya: jumlah tabungan akhir (A)."},{"langkah":"Rencanakan","isi":"Lama menabung dalam bulan, jadi t = 15/12 tahun. Rumus: B = M × (p/100) × t, lalu A = M + B."},{"langkah":"Hitung","isi":"B = 4.800.000 × (7,5/100) × (15/12) = 450.000. A = 4.800.000 + 450.000 = 5.250.000. Jadi jumlah tabungan akhir Rp5.250.000."},{"langkah":"Periksa","isi":"Jumlah tabungan akhir lebih besar dari modal awal, dan A − M = Rp450.000 sama dengan besar bunga. Cocok."}]'::jsonb, '[{"jenis":"SATUAN_WAKTU","nilai":10200000,"pesan":"Lama menabung dalam bulan. Ubah dulu ke tahun: 15 bulan = 15/12 tahun."},{"jenis":"PERSEN","nilai":49800000,"pesan":"Ingat, suku bunga 7,5% ditulis p/100 = 7,5/100 di dalam rumus."},{"jenis":"TERTUKAR_BUNGA_TABUNGAN","nilai":450000,"pesan":"Yang ditanya adalah jumlah tabungan akhir (A), yaitu A = M + B."}]'::jsonb)
